def _policy_command(args, policies: PolicyStore) -> int:
    """Handle `policy show|set|delete|check`; management is read-only."""
    tenant_id = args.tenant_id
    if not tenant_id:
        return _fail("field tenant_id must be a non-empty string", 2)

    if args.policy_command == "check":
        subject = args.subject
        if not isinstance(subject, str) or not subject:
            return _fail(
                "field subject must be a non-empty string", 2
            )
        action = args.action
        if not isinstance(action, str) or not action:
            return _fail(
                "field action must be a non-empty string", 2
            )
        if action not in POLICY_ACTIONS:
            return _fail(
                "field action has unknown action %r (allowed: %s)"
                % (action, ", ".join(POLICY_ACTIONS)),
                2,
            )
        try:
            result = policies.check(tenant_id, subject, action)
        except PolicyStoreUnavailable:
            return _fail("policy store is unavailable", 1)
        _print(
            {
                "tenant_id": tenant_id,
                "subject": subject,
                "action": action,
                "allowed": result["allowed"],
                "effect": result["effect"],
                "reason": result["reason"],
                "rules": [rule.to_json() for rule in result["rules"]],
            }
        )
        return 0

    if args.policy_command == "show":
        rules = policies.get(tenant_id)
        if rules is None:
            return _fail("policy not found", 4)
        try:
            policies.audit_read(tenant_id)
        except LedgerError as exc:
            return _ledger_fail(exc)
        _print(
            {"tenant_id": tenant_id,
             "rules": [r.to_json() for r in rules],
             "revision": revision_for_rules(rules)}
        )
        return 0

    if args.policy_command == "set":
        expected = None
        if args.expected_revision is not None:
            try:
                expected = validate_expected_revision(
                    args.expected_revision
                )
            except PolicyError as exc:
                return _fail(str(exc), 2)
        try:
            raw = json.loads(args.rules)
        except ValueError:
            return _fail("field rules must be valid JSON", 2)
        try:
            rules = validate_rules(raw)
        except PolicyError as exc:
            return _fail(str(exc), 2)
        try:
            rules, new_revision = policies.put(
                tenant_id, rules, expected_revision=expected
            )
        except PolicyRevisionConflict as exc:
            return _revision_conflict(exc)
        except LedgerError as exc:
            return _ledger_fail(exc)
        _print(
            {"tenant_id": tenant_id,
             "rules": [r.to_json() for r in rules],
             "revision": new_revision}
        )
        return 0

    # policy delete
    expected = None
    if args.expected_revision is not None:
        try:
            expected = validate_expected_revision(args.expected_revision)
        except PolicyError as exc:
            return _fail(str(exc), 2)
    try:
        policies.delete(tenant_id, expected_revision=expected)
    except PolicyRevisionConflict as exc:
        return _revision_conflict(exc)
    except LedgerError as exc:
        return _ledger_fail(exc)
    _print({"tenant_id": tenant_id, "deleted": True})
    return 0

