"""Cross-process crash-recovery tests driven through the real CLI.

A crash is injected deterministically: the test process holds the exclusive
flock on ``audit.log.lock``, so the CLI subprocess blocks exactly at the
commit-point ledger append (after every provider handle, journal, marker and
snapshot is already durable). SIGKILL then simulates the process dying at the
worst possible moment; the next CLI invocation must settle the scene.
"""

import fcntl
import json
import os
import signal
import subprocess
import sys
import time

import pytest

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TESTS_DIR = os.path.dirname(os.path.abspath(__file__))


def _cli_env():
    env = dict(os.environ)
    env["PYTHONPATH"] = TESTS_DIR + os.pathsep + REPO_ROOT
    return env


def run_cli(env, *args, timeout=60):
    cmd = [sys.executable, "-m", "keymgr", "--data-dir", env.data_dir] + [
        str(a) for a in args
    ]
    return subprocess.run(
        cmd, capture_output=True, text=True, env=_cli_env(), timeout=timeout
    )


def start_cli(env, *args):
    cmd = [sys.executable, "-m", "keymgr", "--data-dir", env.data_dir] + [
        str(a) for a in args
    ]
    return subprocess.Popen(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        env=_cli_env(),
    )


def wait_for(predicate, timeout=15.0):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if predicate():
            return True
        time.sleep(0.05)
    return False




class Client:
    def __init__(self, base):
        self.base = base

    def call(self, method, path, body=None, operator="alice", headers=None):
        data = json.dumps(body).encode() if body is not None else None
        h = {"X-Operator-Id": operator}
        if data is not None:
            h["Content-Type"] = "application/json"
        if headers:
            h.update(headers)
        req = urllib.request.Request(
            self.base + path, data=data, method=method, headers=h
        )
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                return resp.status, json.loads(resp.read())
        except urllib.error.HTTPError as exc:
            return exc.code, json.loads(exc.read())


@pytest.fixture()
def stack(tmp_path, monkeypatch):
    yield from _build_server(tmp_path, monkeypatch)


_idem_counter = itertools.count(1)


def _idem(prefix="op"):
    return "%s-%d" % (prefix, next(_idem_counter))


def _make_key(client, algorithm="AES256", tenant="t"):
    status, body = client.call(
        "POST", "/v1/keys",
        {"tenant_id": tenant, "algorithm": algorithm, "label": "k"},
    )
    assert status == 201, body

